e_k(T(v)) &= -\sum_{i=1}^k\! \left(\frac{\prod_{j=1}^{k+1}( v_{k,i}- v_{k+1,j})}{\prod_{j\neq i}^{k}( v_{k,i}- v_{k,j})}\!\right)T(v+\delta^{k,i}),\\[1mm]
f_k(T(v)) &= \sum_{i=1}^k\! \left(\frac{\prod_{j=1}^{k-1}( v_{k,i}- v_{k-1,j})}{\prod_{j\neq i}^{k}( v_{k,i}- v_{k,j})}\!\right)T(v-\delta^{k,i}),\\[1mm]
h_k(T(v)) &= \left(2\sum_{i=1}^k v_{k,i}-\sum_{i=1}^{k-1} v_{k-1,i}-\sum_{i=1}^{k+1} v_{k+1,i}-1\!\right)T(v),
\end{aligned}
